-- FR-M0-11: only the independent migration administrator owns objects.
BEGIN;
SET ROLE inves_cog_admin;
CREATE EXTENSION IF NOT EXISTS vector;
REVOKE CREATE ON SCHEMA public FROM PUBLIC;
ALTER DEFAULT PRIVILEGES FOR ROLE inves_cog_admin REVOKE EXECUTE ON FUNCTIONS FROM PUBLIC;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'role_ingest') THEN CREATE ROLE role_ingest NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'role_trading') THEN CREATE ROLE role_trading NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'role_marketstate') THEN CREATE ROLE role_marketstate NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'role_valuation') THEN CREATE ROLE role_valuation NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'role_perception') THEN CREATE ROLE role_perception NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'role_overlay') THEN CREATE ROLE role_overlay NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'role_shadow') THEN CREATE ROLE role_shadow NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'role_web') THEN CREATE ROLE role_web NOLOGIN NOINHERIT NOSUPERUSER NOCREATEDB NOCREATEROLE; END IF; END $$;
CREATE SCHEMA IF NOT EXISTS ingest AUTHORIZATION inves_cog_admin;
REVOKE ALL ON SCHEMA ingest FROM PUBLIC, role_ingest, role_trading, role_marketstate, role_valuation, role_perception, role_overlay, role_shadow, role_web;
REVOKE ALL ON ALL TABLES IN SCHEMA ingest FROM PUBLIC, role_ingest, role_trading, role_marketstate, role_valuation, role_perception, role_overlay, role_shadow, role_web;
REVOKE ALL ON ALL SEQUENCES IN SCHEMA ingest FROM PUBLIC, role_ingest, role_trading, role_marketstate, role_valuation, role_perception, role_overlay, role_shadow, role_web;
ALTER DEFAULT PRIVILEGES FOR ROLE inves_cog_admin IN SCHEMA ingest REVOKE ALL ON TABLES FROM PUBLIC, role_ingest, role_trading, role_marketstate, role_valuation, role_perception, role_overlay, role_shadow, role_web;
ALTER DEFAULT PRIVILEGES FOR ROLE inves_cog_admin IN SCHEMA ingest REVOKE ALL ON SEQUENCES FROM PUBLIC, role_ingest, role_trading, role_marketstate, role_valuation, role_perception, role_overlay, role_shadow, role_web;
ALTER DEFAULT PRIVILEGES FOR ROLE inves_cog_admin IN SCHEMA ingest REVOKE ALL ON FUNCTIONS FROM PUBLIC, role_ingest, role_trading, role_marketstate, role_valuation, role_perception, role_overlay, role_shadow, role_web;
GRANT USAGE ON SCHEMA ingest TO role_ingest;
GRANT SELECT, INSERT, UPDATE, DELETE ON ALL TABLES IN SCHEMA ingest TO role_ingest;
ALTER DEFAULT PRIVILEGES FOR ROLE inves_cog_admin IN SCHEMA ingest GRANT SELECT, INSERT, UPDATE, DELETE ON TABLES TO role_ingest;
